pub struct Solution;

impl Solution {
    pub fn get_permutation(n: i32, k: i32) -> String {
        let n_usize = n as usize;
        let mut k_idx = k - 1;
        let mut numbers: Vec<i32> = (1..=n).collect();
        let mut fact = vec![1; n_usize];

        for i in 1..n_usize {
            fact[i] = fact[i - 1] * (i as i32);
        }

        let mut result = String::with_capacity(n_usize);

        for i in (0..n_usize).rev() {
            let idx = (k_idx / fact[i]) as usize;
            k_idx %= fact[i];
            let num = numbers.remove(idx);
            result.push((b'0' + num as u8) as char);
        }

        result
    }
}

